<template>
  <div class="traffic-chart">
    <div class="chart-readout" aria-live="polite"><span>{{ active ? date(active.date) : 'Daily activity' }}</span><strong>{{ active ? format(active[metric]) : 'Move across the chart' }}</strong></div>
    <svg viewBox="0 0 760 190" role="img" :aria-label="`${label} by day`" @pointerleave="selected = null">
      <defs><linearGradient id="traffic-chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="currentColor" stop-opacity=".12"/><stop offset="1" stop-color="currentColor" stop-opacity="0"/></linearGradient></defs>
      <g class="chart-grid"><line v-for="y in [20,65,110,155]" :key="y" x1="10" x2="750" :y1="y" :y2="y"/></g>
      <path v-if="points.length" :d="area" fill="url(#traffic-chart-fill)"/>
      <path :d="line" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/>
      <g v-for="(point,index) in points" :key="point.date" class="chart-point" @pointerenter="selected = index">
        <circle :cx="point.x" :cy="point.y" :r="selected === index ? 4 : 2" fill="currentColor"/>
        <rect :x="point.x-hitWidth/2" y="0" :width="hitWidth" height="170" fill="transparent"/>
      </g>
      <line v-if="activePoint" :x1="activePoint.x" :x2="activePoint.x" y1="12" y2="160" class="chart-guide"/>
      <g class="chart-labels"><text x="10" y="187">{{ shortDate(series[0]?.date) }}</text><text x="750" y="187" text-anchor="end">{{ shortDate(series.at(-1)?.date) }}</text></g>
    </svg>
    <input v-if="series.length" v-model.number="selected" type="range" min="0" :max="series.length-1" :aria-label="`Inspect daily ${label.toLowerCase()}`" class="chart-range"/>
  </div>
</template>
<script setup>
/* global defineProps */
import { ref, computed } from 'vue';
const props=defineProps({ series:{type:Array,default:()=>[]}, metric:{type:String,default:'sessions'}, label:{type:String,default:'Sessions'} });
const selected=ref(null);
const maximum=computed(()=>Math.max(1,...props.series.map(row=>row[props.metric]||0)));
const points=computed(()=>props.series.map((row,i)=>({...row,x:10+i*740/Math.max(1,props.series.length-1),y:155-(row[props.metric]||0)/maximum.value*125})));
const hitWidth=computed(()=>740/Math.max(1,props.series.length-1));
const line=computed(()=>points.value.map((p,i)=>`${i?'L':'M'}${p.x},${p.y}`).join(' '));
const area=computed(()=>`${line.value} L750,155 L10,155 Z`);
const active=computed(()=>selected.value===null?null:props.series[selected.value]);
const activePoint=computed(()=>selected.value===null?null:points.value[selected.value]);
const date=value=>new Date(`${value}T12:00:00Z`).toLocaleDateString('en',{month:'short',day:'numeric',weekday:'short'});
const shortDate=value=>value?new Date(`${value}T12:00:00Z`).toLocaleDateString('en',{month:'short',day:'numeric'}):'';
function format(value){return props.metric==='visible_ms'?`${Math.round(value/60000)} min`:Number(value||0).toLocaleString('en');}
</script>
<style scoped>
.traffic-chart{color:var(--traffic-accent)}.chart-readout{display:flex;justify-content:space-between;gap:1rem;min-height:2rem;font: .72rem var(--traffic-font);color:var(--traffic-muted);font-variant-numeric:tabular-nums}.chart-readout strong{font-weight:400;color:var(--traffic-ink)}svg{display:block;width:100%;overflow:visible}.chart-grid line{stroke:var(--traffic-line);stroke-dasharray:2 5}.chart-guide{stroke:currentColor;opacity:.35;stroke-dasharray:3 4;pointer-events:none}.chart-labels{fill:var(--traffic-muted);font:11px var(--traffic-font)}.chart-point{cursor:crosshair}.chart-range{width:100%;height:3px;accent-color:var(--traffic-accent);opacity:0;transition:opacity 120ms}.traffic-chart:focus-within .chart-range{opacity:1}@media(hover:none){.chart-range{opacity:.5;height:10px}}
</style>
